use ethos::taint::TaintLevel;
use ethos::walls::{BoundaryPolicyEngine, OuroborosWall};

#[test]
fn test_tainted_exec_egress_is_blocked() {
    let engine = BoundaryPolicyEngine::default();
    let exec_res = engine.evaluate_exec("curl", &["https://unknown.example"], TaintLevel::Untrusted);
    assert!(!exec_res.allowed);
}

#[test]
fn test_ouroboros_blocks_policy_edit() {
    let wall = OuroborosWall::default();
    assert!(wall.is_protected("config/policy.default.yaml"));
}

